import Foundation
import GRDB

/// База приложения: соединение GRDB + схема (миграции).
/// Только Data-слой знает о GRDB; наружу база видна через `ChatRepository`.
struct AppDatabase: Sendable {
    let writer: any DatabaseWriter

    /// Применяет миграции к переданному соединению.
    init(_ writer: any DatabaseWriter) throws {
        self.writer = writer
        try Self.migrator.migrate(writer)
    }

    /// Файл в Application Support. `DatabasePool` — чтения не ждут запись стрима.
    static func onDisk(fileName: String = "AIChat.sqlite") throws -> AppDatabase {
        let folder = try FileManager.default.url(
            for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true
        )
        let url = folder.appendingPathComponent(fileName, isDirectory: false)
        return try AppDatabase(DatabasePool(path: url.path, configuration: makeConfiguration()))
    }

    /// Для тестов и превью: каждая база — отдельная, живёт, пока жив объект.
    static func inMemory() throws -> AppDatabase {
        try AppDatabase(DatabaseQueue(configuration: makeConfiguration()))
    }

    private static func makeConfiguration() -> Configuration {
        var configuration = Configuration()
        // По умолчанию так и есть, но каскадное удаление сообщений держится именно на этом.
        configuration.foreignKeysEnabled = true
        return configuration
    }

    // MARK: Миграции

    /// Схема. Опубликованные миграции не меняются — только новые `registerMigration`.
    static var migrator: DatabaseMigrator {
        var migrator = DatabaseMigrator()
        #if DEBUG
        // Пока схема в разработке, при её изменении база пересоздаётся.
        migrator.eraseDatabaseOnSchemaChange = true
        #endif

        migrator.registerMigration("v1") { db in
            // Таблицы с UUID-ключом сохраняют rowid — он задаёт порядок вставки.
            try db.create(table: ChatRecord.databaseTableName) { t in
                t.primaryKey("id", .blob)
                t.column("title", .text).notNull()
                t.column("createdAt", .double).notNull()
                t.column("updatedAt", .double).notNull().indexed()
            }

            try db.create(table: MessageRecord.databaseTableName) { t in
                t.primaryKey("id", .blob)
                t.belongsTo(ChatRecord.databaseTableName, onDelete: .cascade)
                    .notNull()
                t.column("role", .text).notNull()
                t.column("text", .text).notNull()
                t.column("status", .text).notNull().indexed()
                t.column("failureKind", .text)
                t.column("failureRetryAt", .double)
                t.column("createdAt", .double).notNull()
            }
            try db.create(
                index: "message_on_chatId_createdAt",
                on: MessageRecord.databaseTableName,
                columns: ["chatId", "createdAt"]
            )
        }
        return migrator
    }
}

/// В базе лежит значение, которого нет в доменном перечислении.
struct InvalidDatabaseValue: Error, Hashable, Sendable {
    let column: String
    let value: String
}

import Foundation
import GRDB

/// Строка таблицы `chat`. Доменный `Chat` о GRDB не знает — переводим здесь.
struct ChatRecord: Codable, Hashable, Sendable {
    static let databaseTableName = "chat"

    var id: UUID
    var title: String
    var createdAt: Date
    var updatedAt: Date

    enum Columns {
        static let id = Column(CodingKeys.id)
        static let title = Column(CodingKeys.title)
        static let createdAt = Column(CodingKeys.createdAt)
        static let updatedAt = Column(CodingKeys.updatedAt)
    }
}

extension ChatRecord: FetchableRecord, PersistableRecord {
    // Даты — числом: текстовый формат GRDB по умолчанию режет до миллисекунд,
    // и прочитанное значение не совпало бы с записанным.
    static func databaseDateEncodingStrategy(for column: String) -> DatabaseDateEncodingStrategy {
        .timeIntervalSinceReferenceDate
    }

    static func databaseDateDecodingStrategy(for column: String) -> DatabaseDateDecodingStrategy {
        .timeIntervalSinceReferenceDate
    }
}

extension ChatRecord {
    init(_ chat: Chat) {
        id = chat.id
        title = chat.title
        createdAt = chat.createdAt
        updatedAt = chat.updatedAt
    }

    var chat: Chat {
        Chat(id: id, title: title, createdAt: createdAt, updatedAt: updatedAt)
    }

    /// Чаты, новые (по `updatedAt`) сверху.
    static func byLastActivity() -> QueryInterfaceRequest<ChatRecord> {
        order(Columns.updatedAt.desc, Columns.createdAt.desc, Column.rowID.desc)
    }
}

extension Date {
    /// Значение даты в SQL-аргументах — в том же виде, что и в колонках записей.
    var databaseTimestamp: Double { timeIntervalSinceReferenceDate }
}

import Foundation
import GRDB

/// Строка таблицы `message`. `MessageFailure` разложен на две колонки.
struct MessageRecord: Codable, Hashable, Sendable {
    static let databaseTableName = "message"

    var id: UUID
    var chatId: UUID
    var role: String
    var text: String
    var status: String
    var failureKind: String?
    var failureRetryAt: Date?
    var createdAt: Date

    enum Columns {
        static let id = Column(CodingKeys.id)
        static let chatId = Column(CodingKeys.chatId)
        static let role = Column(CodingKeys.role)
        static let text = Column(CodingKeys.text)
        static let status = Column(CodingKeys.status)
        static let failureKind = Column(CodingKeys.failureKind)
        static let failureRetryAt = Column(CodingKeys.failureRetryAt)
        static let createdAt = Column(CodingKeys.createdAt)
    }
}

extension MessageRecord: FetchableRecord, PersistableRecord {
    // См. `ChatRecord`: даты храним числом, без потери точности.
    static func databaseDateEncodingStrategy(for column: String) -> DatabaseDateEncodingStrategy {
        .timeIntervalSinceReferenceDate
    }

    static func databaseDateDecodingStrategy(for column: String) -> DatabaseDateDecodingStrategy {
        .timeIntervalSinceReferenceDate
    }
}

extension MessageRecord {
    init(_ message: Message) {
        id = message.id
        chatId = message.chatId
        role = message.role.rawValue
        text = message.text
        status = message.status.rawValue
        failureKind = message.failure?.kind.rawValue
        failureRetryAt = message.failure?.retryAt
        createdAt = message.createdAt
    }

    /// - Throws: `InvalidDatabaseValue`, если в базе неизвестные роль, статус или вид ошибки.
    func message() throws -> Message {
        guard let role = MessageRole(rawValue: role) else {
            throw InvalidDatabaseValue(column: "role", value: role)
        }
        guard let status = MessageStatus(rawValue: status) else {
            throw InvalidDatabaseValue(column: "status", value: status)
        }
        var failure: MessageFailure?
        if let failureKind {
            guard let kind = ErrorKind(rawValue: failureKind) else {
                throw InvalidDatabaseValue(column: "failureKind", value: failureKind)
            }
            failure = MessageFailure(kind: kind, retryAt: failureRetryAt)
        }
        return Message(id: id, chatId: chatId, role: role, text: text, status: status,
                       failure: failure, createdAt: createdAt)
    }

    /// Порядок сообщений: по времени, при равенстве — по порядку вставки.
    static func chronological() -> QueryInterfaceRequest<MessageRecord> {
        order(Columns.createdAt, Column.rowID)
    }
}

